-- 1105: Rapid Prototyping calculators -- laser sintering, 3D printing, stereolithography, part curing and per-feature cleaning as real database calculators.
--
-- GENERATED by scripts/generate-rapid-prototyping-calculators-migration.ts from
-- src/modules/bom-items/costing/additive/calculators/rapid-prototyping-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- Rapid Prototyping was staged (reference data 2026-RapidProto: 90 variables, 2 lookup tables; 25 HR Rates machines, 50 materials)
-- but had no cost engine: its five catalog processes had no calculator, and a part whose Process is Rapid Prototyping was not costed.
-- It is priced by the additive engine in its own domain (costing/additive/additive-domain.ts RAPID_PROTOTYPING): these are the
-- calculators of its three build routes (laser sintering, 3D printing, stereolithography), part curing, and cleaning timed per hole and
-- void; the parts per build, the powder, resin and support material, the build gas, the laser use and one feature's cleaning time are
-- helpers the engine runs per part, which no operation maps to.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Rapid Prototyping catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Rapid Prototyping - Parts per build
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Rapid Prototyping - Parts per build$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Rapid Prototyping - Parts per build$q$, 'process', 'single', false, true, true, $q$How many parts one build takes: the part's footprint on the plate, with the nesting allowance (nestingAllowance, 0.75 mm in memory/Rapid prototyping) on each side, laid in rows on the machine's bed, the better of the two ways round; a powder bed (SLS) also stacks them in height. Rapid Prototyping holds no base layers under the stack. Capped by the batch.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$How many parts one build takes: the part's footprint on the plate, with the nesting allowance (nestingAllowance, 0.75 mm in memory/Rapid prototyping) on each side, laid in rows on the machine's bed, the better of the two ways round; a powder bed (SLS) also stacks them in height. Rapid Prototyping holds no base layers under the stack. Capped by the batch.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Bed Length$q$, $q$Bed Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Bed Width$q$, $q$Bed Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Bed Height$q$, $q$Bed Height (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Part Length$q$, $q$Part Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Part Width$q$, $q$Part Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Build Height$q$, $q$Build Height (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Nesting Allowance$q$, $q$Nesting Allowance (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Stacks$q$, $q$Stacks$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Batch Size$q$, $q$Batch Size$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Parts per Layer$q$, $q$Parts per Layer$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$max(floor({Bed Length} / ({Part Length} + 2 * {Nesting Allowance})) * floor({Bed Width} / ({Part Width} + 2 * {Nesting Allowance})), floor({Bed Length} / ({Part Width} + 2 * {Nesting Allowance})) * floor({Bed Width} / ({Part Length} + 2 * {Nesting Allowance})))$q$, 10, false),
    (v_id, $q$Parts Stacked$q$, $q$Parts Stacked$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q${Stacks} > 0 ? max(1, floor({Bed Height} / ({Build Height} + 2 * {Nesting Allowance}))) : 1$q$, 11, false),
    (v_id, $q$Parts per Build$q$, $q$Parts per Build$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$max(1, min({Batch Size}, {Parts per Layer} * {Parts Stacked}))$q$, 12, false);
END
$calc$;

-- Rapid Prototyping - SLS powder
