  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Part Volume$q$, $q$Part Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Density$q$, $q$Density (kg/m³)$q$, $q$number$q$, $q$kg/m³$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Bed Length$q$, $q$Bed Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Bed Width$q$, $q$Bed Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Bed Fill Height$q$, $q$Bed Fill Height (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Parts per Build$q$, $q$Parts per Build$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Recovery Fraction$q$, $q$Recovery Fraction$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Unit Cost$q$, $q$Unit Cost (USD/kg)$q$, $q$number$q$, $q$USD/kg$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Part Mass$q$, $q$Part Mass (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q${Part Volume} * {Density} / 1000000000$q$, 9, false),
    (v_id, $q$Bed Powder Mass$q$, $q$Bed Powder Mass (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q${Bed Length} * {Bed Width} * {Bed Fill Height} * {Density} / 1000000000$q$, 10, false),
    (v_id, $q$Spent Powder Mass$q$, $q$Spent Powder Mass (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q$max(0, {Bed Powder Mass} - {Parts per Build} * {Part Mass}) * (1 - {Recovery Fraction}) / max({Parts per Build}, 1)$q$, 11, false),
    (v_id, $q$Material Cost$q$, $q$Material Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q$({Part Mass} + {Spent Powder Mass}) * {Unit Cost}$q$, 12, false);
END
$calc$;

