-- Rapid Prototyping - Stereolithography
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Rapid Prototyping - Stereolithography$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Rapid Prototyping - Stereolithography$q$, 'process', 'single', false, true, true, $q$Stereolithography (SLA), per part. Every layer at slaStandardLayerResolution is wiped across the bed (the bed length at the machine's wiper speed) and waits the machine's layer delay; each part and its supports (slaSupportVolumeFraction of the support volume) are cured by the laser at the machine's speed and beam. The build's preprocessing (slaPreprocessingTime) is shared by its parts.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Stereolithography (SLA), per part. Every layer at slaStandardLayerResolution is wiped across the bed (the bed length at the machine's wiper speed) and waits the machine's layer delay; each part and its supports (slaSupportVolumeFraction of the support volume) are cured by the laser at the machine's speed and beam. The build's preprocessing (slaPreprocessingTime) is shared by its parts.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Build Height$q$, $q$Build Height (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Layer Thickness$q$, $q$Layer Thickness (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Bed Length$q$, $q$Bed Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Wiper Speed$q$, $q$Wiper Speed (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Layer Delay$q$, $q$Layer Delay (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Part Volume$q$, $q$Part Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Support Volume$q$, $q$Support Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Support Fraction$q$, $q$Support Fraction$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Scanning Speed$q$, $q$Scanning Speed (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Beam Diameter$q$, $q$Beam Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 10, true),
    (v_id, $q$Parts per Build$q$, $q$Parts per Build$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 11, true),
    (v_id, $q$Preprocessing Time$q$, $q$Preprocessing Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 12, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 13, true),
    (v_id, $q$Layers$q$, $q$Layers$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$ceil({Build Height} / {Layer Thickness})$q$, 14, false),
    (v_id, $q$Layer Time$q$, $q$Layer Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Bed Length} / {Wiper Speed} + {Layer Delay}$q$, 15, false),
    (v_id, $q$Scan Time$q$, $q$Scan Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Part Volume} + {Support Volume} * {Support Fraction}) / ({Scanning Speed} * {Beam Diameter} * {Layer Thickness})$q$, 16, false),
    (v_id, $q$Build Time$q$, $q$Build Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Layers} * {Layer Time} + {Parts per Build} * {Scan Time}$q$, 17, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Build Time} + {Preprocessing Time}) / {Parts per Build} * {Cycle Time Factor}$q$, 18, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Rapid Prototyping - Stereolithography$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Rapid Prototyping$q$ AND operation IN ($q$Resin Curing$q$);
END
$calc$;

-- Rapid Prototyping - Part curing
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Rapid Prototyping - Part curing$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Rapid Prototyping - Part curing$q$, 'process', 'single', false, true, true, $q$Post-curing in an oven (a stereolithography part in a ProCure or AaroCure oven, a LaserForm part in the LaserForm oven): one cure (curingMaxCureTime) per oven load, shared by the parts the oven's bed takes (Rapid Prototyping - Parts per build on the oven).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Post-curing in an oven (a stereolithography part in a ProCure or AaroCure oven, a LaserForm part in the LaserForm oven): one cure (curingMaxCureTime) per oven load, shared by the parts the oven's bed takes (Rapid Prototyping - Parts per build on the oven).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Cure Time$q$, $q$Cure Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Parts per Load$q$, $q$Parts per Load$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Cure Time} / max({Parts per Load}, 1) * {Cycle Time Factor}$q$, 4, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Rapid Prototyping - Part curing$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Rapid Prototyping$q$ AND operation IN ($q$Part Curing$q$);
END
$calc$;

-- Rapid Prototyping - Feature cleaning
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Rapid Prototyping - Feature cleaning$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Rapid Prototyping - Feature cleaning$q$, 'process', 'single', false, true, true, $q$The time to clear the loose powder or uncured resin from one hole or void (memory/Rapid prototyping cleaning* variables): its type's base time, times a multiplier of its size (a hole's diameter, a void's volume: below the Small limit the Small multiplier, above the Large limit the Large one, else the Medium one) and one of its depth (likewise). The engine seeds each input from the variable of the feature's type (simple, multi-step, ringed and complex holes; simple, ringed and complex voids).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The time to clear the loose powder or uncured resin from one hole or void (memory/Rapid prototyping cleaning* variables): its type's base time, times a multiplier of its size (a hole's diameter, a void's volume: below the Small limit the Small multiplier, above the Large limit the Large one, else the Medium one) and one of its depth (likewise). The engine seeds each input from the variable of the feature's type (simple, multi-step, ringed and complex holes; simple, ringed and complex voids).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Base Time$q$, $q$Base Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Size$q$, $q$Size$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Small Size Limit$q$, $q$Small Size Limit$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Large Size Limit$q$, $q$Large Size Limit$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Small Size Multiplier$q$, $q$Small Size Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Medium Size Multiplier$q$, $q$Medium Size Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Large Size Multiplier$q$, $q$Large Size Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Depth$q$, $q$Depth (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Small Depth Limit$q$, $q$Small Depth Limit (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Large Depth Limit$q$, $q$Large Depth Limit (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 10, true),
    (v_id, $q$Small Depth Multiplier$q$, $q$Small Depth Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 11, true),
    (v_id, $q$Medium Depth Multiplier$q$, $q$Medium Depth Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 12, true),
    (v_id, $q$Large Depth Multiplier$q$, $q$Large Depth Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 13, true),
    (v_id, $q$Size Multiplier$q$, $q$Size Multiplier$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q${Size} < {Small Size Limit} ? {Small Size Multiplier} : ({Size} > {Large Size Limit} ? {Large Size Multiplier} : {Medium Size Multiplier})$q$, 14, false),
    (v_id, $q$Depth Multiplier$q$, $q$Depth Multiplier$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q${Depth} < {Small Depth Limit} ? {Small Depth Multiplier} : ({Depth} > {Large Depth Limit} ? {Large Depth Multiplier} : {Medium Depth Multiplier})$q$, 15, false),
    (v_id, $q$Cleaning Time$q$, $q$Cleaning Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Base Time} * {Size Multiplier} * {Depth Multiplier}$q$, 16, false);
END
$calc$;

-- Rapid Prototyping - Cleaning
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Rapid Prototyping - Cleaning$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Rapid Prototyping - Cleaning$q$, 'process', 'single', false, true, true, $q$Cleaning the built part: the base time every part takes (cleaningBaseTime), plus the time of each of its holes and voids (Rapid Prototyping - Feature cleaning, summed by the engine over the holes and voids the cad-engine recognised).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Cleaning the built part: the base time every part takes (cleaningBaseTime), plus the time of each of its holes and voids (Rapid Prototyping - Feature cleaning, summed by the engine over the holes and voids the cad-engine recognised).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Base Time$q$, $q$Base Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Feature Time$q$, $q$Feature Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Base Time} + {Feature Time}) * {Cycle Time Factor}$q$, 4, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Rapid Prototyping - Cleaning$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Rapid Prototyping$q$ AND operation IN ($q$Cleaning$q$);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Rapid Prototyping - Parts per build$q$, 12, 0),
    ($q$Rapid Prototyping - SLS powder$q$, 12, 0),
    ($q$Rapid Prototyping - Resin and support material$q$, 10, 0),
    ($q$Rapid Prototyping - Build gas$q$, 5, 0),
    ($q$Rapid Prototyping - Laser use$q$, 4, 0),
    ($q$Rapid Prototyping - Laser sintering$q$, 13, 1),
    ($q$Rapid Prototyping - 3D printing$q$, 14, 1),
    ($q$Rapid Prototyping - Stereolithography$q$, 18, 1),
    ($q$Rapid Prototyping - Part curing$q$, 4, 1),
    ($q$Rapid Prototyping - Feature cleaning$q$, 16, 0),
    ($q$Rapid Prototyping - Cleaning$q$, 4, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Rapid Prototyping$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1105: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
